package org.marketreview.nativeapp;
import org.json.*;import java.util.*;import static org.marketreview.nativeapp.WatchlistWorkspaceModel.*;
final class IndustryVersionCatalog {
 static JSONArray catalog(JSONArray reports,JSONArray topics)throws Exception{
  JSONArray out=new JSONArray();Set<String> complete=new HashSet<>();Map<String,String> names=new HashMap<>();for(int i=0;i<topics.length();i++){JSONObject t=topics.getJSONObject(i);names.put(t.getString("id"),t.optString("name"));}
  for(int i=0;i<reports.length();i++){JSONObject r=reports.getJSONObject(i);if(!"industry_research_archive".equals(r.optString("legacySource")))continue;IndustryReportArchive.Parsed p=IndustryReportArchive.validate(r.getString("text"));JSONArray ts=p.data.getJSONArray("topics");
   for(int k=0;k<ts.length();k++){JSONObject t=ts.getJSONObject(k);String id=t.getString("id");JSONArray versions=new JSONArray(),runs=new JSONArray();for(String key:new String[]{"versions","runs"}){JSONArray values=p.data.getJSONArray(key);for(int j=0;j<values.length();j++)if(id.equals(values.getJSONObject(j).optString("topicId")))(key.equals("versions")?versions:runs).put(values.getJSONObject(j));}
    complete.add(id);out.put(object("key",r.getString("id")+"\u001f"+id,"archiveId",r.get("id"),"topicId",id,"name",t.get("name"),"complete",true,"topic",t,"versions",versions,"evidence",p.data.get("evidence"),"runs",runs,"currentVersionId",t.get("currentVersionId")));
   }
  }
  TreeMap<String,JSONArray> partial=new TreeMap<>();for(int i=0;i<reports.length();i++){JSONObject r=reports.getJSONObject(i);if(!"industry_research_versions".equals(r.optString("legacySource")))continue;JSONObject p=IndustryReportArchive.json(new LegacyResearchJson.Parser(r.getString("text")).run());String id=p.optString("topicId");if(complete.contains(id))continue;need(!id.isEmpty()&&p.opt("id") instanceof String,"已有旧报告身份缺失");JSONObject v=object("id",p.get("id"),"topicId",id,"sequence",p.opt("sequence"),"previousVersionId",p.opt("previousVersionId"),"contentHash",p.opt("contentHash"),"createdAt",p.opt("createdAt"),"payload",p);partial.computeIfAbsent(id,k->new JSONArray()).put(v);}
  for(Map.Entry<String,JSONArray> e:partial.entrySet())out.put(object("key","partial:"+e.getKey(),"topicId",e.getKey(),"name",names.getOrDefault("legacy-topic:"+e.getKey(),e.getKey()),"complete",false,"versions",e.getValue(),"currentVersionId",JSONObject.NULL));return out;
 }
 static JSONObject version(JSONObject group,String id)throws Exception{JSONArray vs=group.getJSONArray("versions");for(int i=0;i<vs.length();i++)if(id.equals(vs.getJSONObject(i).optString("id")))return vs.getJSONObject(i);return new JSONObject();}
 static String report(JSONObject group,String id)throws Exception{JSONObject v=version(group,id);return v.length()==0?"未选择版本":"历史原件只读；原 verified 不等于当前人工已核验\n原ID："+id+"\n原contentHash："+v.optString("contentHash")+"\n原前版："+v.optString("previousVersionId")+"\n\n完整版本：\n"+v.toString(2);}
 static String context(JSONObject group)throws Exception{return !group.optBoolean("complete")?"已有旧报告正文可读；完整配置、运行记录及原当前指针尚未提供。":"历史任务保持停用；原当前指针："+(group.isNull("currentVersionId")?"无":group.optString("currentVersionId"))+"\n完整主题配置、运行关联和证据原件：\n"+object("topic",group.get("topic"),"runs",group.get("runs"),"evidence",group.get("evidence")).toString(2);}
 static JSONObject difference(JSONObject group,String from,String to)throws Exception{
  JSONObject a=version(group,from).optJSONObject("payload"),b=version(group,to).optJSONObject("payload");if(a==null)a=new JSONObject();if(b==null)b=new JSONObject();Map<String,JSONObject>left=new TreeMap<>(),right=new TreeMap<>();JSONArray av=a.optJSONArray("relations"),bv=b.optJSONArray("relations");if(av!=null)for(int i=0;i<av.length();i++)left.put(av.getJSONObject(i).getString("id"),av.getJSONObject(i));if(bv!=null)for(int i=0;i<bv.length();i++)right.put(bv.getJSONObject(i).getString("id"),bv.getJSONObject(i));Set<String>ids=new TreeSet<>(left.keySet());ids.addAll(right.keySet());JSONArray rows=new JSONArray();for(String id:ids)rows.put(object("id",id,"change",!left.containsKey(id)?"added":!right.containsKey(id)?"removed":equal(left.get(id),right.get(id))?"same":"changed","before",left.containsKey(id)?left.get(id):JSONObject.NULL,"after",right.containsKey(id)?right.get(id):JSONObject.NULL));
  return object("fromVersionId",from,"toVersionId",to,"relations",rows,"beforeEvidenceIds",a.opt("evidenceIds"),"afterEvidenceIds",b.opt("evidenceIds"),"meaning","按原关系ID比较完整记录；不跨公司猜测关联，不代表当前事实核验");
 }
 static JSONArray selectedRelations(JSONObject group,String id)throws Exception{
  JSONObject v=version(group,id),p=v.optJSONObject("payload");JSONArray rs=p==null?new JSONArray():p.optJSONArray("relations"),es=group.optJSONArray("evidence");Map<String,JSONObject> evidence=new HashMap<>();if(es!=null)for(int i=0;i<es.length();i++)evidence.put(es.getJSONObject(i).getString("id"),es.getJSONObject(i));JSONArray out=new JSONArray();
  if(rs!=null)for(int i=0;i<rs.length();i++){JSONObject r=rs.getJSONObject(i),row=new JSONObject(r.toString()),company=r.optJSONObject("company");String rid=r.getString("id");row.put("key",id+":"+rid).put("relationId",rid).put("companyName",company==null?"公司未绑定":company.optString("name","公司未绑定")).put("instrumentId","").put("readOnly",true).put("verification","unverified").put("status","verified".equals(r.optString("status"))?"legacyVerified":"disputed".equals(r.optString("status"))?"disputed":"legacy").put("originalRecord",r).put("versionId",id);
   JSONArray refs=r.optJSONArray("evidenceRefs"),sources=new JSONArray();boolean matched=refs!=null&&refs.length()>0;if(refs!=null)for(int j=0;j<refs.length();j++){JSONObject ref=refs.getJSONObject(j),e=evidence.get(ref.getString("evidenceId"));JSONObject original=e==null?null:e.optJSONObject("payload");String quote=ref.optString("quote");boolean found=original!=null&&!quote.isEmpty()&&original.optString("text").contains(quote);matched&=found;sources.put(object("evidenceId",ref.get("evidenceId"),"quote",ref.get("quote"),"originalUrl",ref.opt("url"),"available",e!=null,"quoteMatched",found,"originalEvidence",e==null?new JSONObject():e));}
   row.put("bodyAvailable",matched).put("sources",sources).put("boundary","仅所选原版本的环节归属；逐字匹配只说明引用在留存正文，历史verified仍需当前复核");out.put(row);
  }return out;
 }
}

